#!/bin/bash
#SBATCH --partition=gpuq
#SBATCH --job-name=twostream-scan
#SBATCH --nodes=1
#SBATCH --gres=gpu:l40s:1
#SBATCH --ntasks-per-node=1
#SBATCH --cpus-per-task=4
#SBATCH --time=2:00:00
#SBATCH --mem=16G
#SBATCH --array=1-10%4
#SBATCH --output=../logs/scan_%A_%a.out
#SBATCH --error=../logs/scan_%A_%a.err

# Numerics scan: one single-GPU job per line of ../inputs/manifest.txt
# ("<tag> <shape_order> <input>"), generated by ../make_scan.py.
# Submit from this scripts/ dir AFTER the baseline looks right:
#   mkdir -p ../logs && sbatch gpu_twostream_scan.sh
# Run one variant only:  sbatch --array=3 gpu_twostream_scan.sh
# %4 caps concurrent tasks so the scan doesn't hog the GPU queue.
# The shape3 line needs entity_s3.xc (SHAPE_ORDER=3 twostream/scripts/build_twostream.sh).

REPO=$HOME/plasma
MANIFEST=$REPO/twostream/runs/scan/inputs/manifest.txt
read -r TAG SHAPE INPUT_REL < <(sed -n "${SLURM_ARRAY_TASK_ID}p" "$MANIFEST")
if [ -z "$TAG" ]; then
  echo "no manifest line ${SLURM_ARRAY_TASK_ID}" >&2
  exit 1
fi
INPUT_FILE=$REPO/$INPUT_REL
ENTITY_BIN=$REPO/twostream/entity_s${SHAPE}.xc
if [ ! -x "$ENTITY_BIN" ]; then
  echo "missing $ENTITY_BIN; build it with SHAPE_ORDER=$SHAPE twostream/scripts/build_twostream.sh" >&2
  exit 1
fi

echo "=== Two-stream scan: $TAG (shape order $SHAPE) ==="
echo "Start: $(date)   Node: $(hostname)   Input: $INPUT_FILE"

module purge
module load cuda/12
# System OpenMPI at runtime; never load the openmpi module (PMIx conflict).
export PATH=/usr/lib64/openmpi/bin:$PATH
export LD_LIBRARY_PATH=/usr/lib64/openmpi/lib:${LD_LIBRARY_PATH:-}
export OMPI_MCA_orte_base_help_aggregate=0

# Output: <WORK_DIR>/twostream_<tag>/
WORK_DIR=/dartfs-hpc/scratch/f007hd2/twostream
mkdir -p $WORK_DIR
cd $WORK_DIR

START_TIME=$(date +%s)
mpirun -np $SLURM_NTASKS \
  --mca pml ob1 \
  --mca btl self,tcp \
  --mca mtl ^ofi \
  --mca osc ^ucx \
  $REPO/twostream/scripts/bind_gpu.sh \
  $ENTITY_BIN -input $INPUT_FILE
EXIT_CODE=$?
END_TIME=$(date +%s)
echo "Elapsed time: $((END_TIME - START_TIME)) seconds"
echo "Exit code: $EXIT_CODE   End: $(date)"
exit $EXIT_CODE
